import math

def combinations(n, k):
    if k < 0 or k > n:
        return 0
    return math.comb(n, k)

def f(r, b):
    return combinations(r, 3) + combinations(b, 3)

n = 7
min_f = float('inf')
best_partition = (0, 0)

# Check all partitions r + b = n
for r in range(n // 2 + 1):
    b = n - r
    current_f = f(r, b)
    if current_f < min_f:
        min_f = current_f
        best_partition = (r, b)

print(f"For n={n}, the minimum value of f(r, b) is: {min_f}")
print(f"Achieved at partition: {best_partition}")
